        a.assign(sz, vector<int>(sz, 0));
        if (ident) {
            for (int i = 0; i < sz; ++i) a[i][i] = 1;
        }
    }
    Matrix operator*(const Matrix& other) const {
        Matrix res(sz);
        for (int i = 0; i < sz; ++i) {
            for (int k = 0; k < sz; ++k) {
                if (a[i][k] == 0) continue;
                long long aik = a[i][k];
                for (int j = 0; j < sz; ++j) {
                    res.a[i][j] = (res.a[i][j] + aik * other.a[k][j]) % MOD;
                }
            }
        }
        return res;
    }
};

Matrix power(Matrix base, long long exp) {
    Matrix res(base.sz, true);
    while (exp > 0) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

struct Node {
    int next[26];
    int link;
    bool term;
    Node() {
        fill(begin(next), end(next), -1);
        link = -1;
        term = false;
    }
};

vector<Node> build_trie(const vector<string>& words) {
    vector<Node> trie(1);
    for (const string& w : words) {
        int v = 0;
        for (char ch : w) {
            int c = ch - 'a';
            if (trie[v].next[c] == -1) {
                trie[v].next[c] = trie.size();
                trie.emplace_back();
            }
            v = trie[v].next[c];
        }
        trie[v].term = true;
    }
    return trie;
}

void build_links(vector<Node>& trie) {
    queue<int> q;
    trie[0].link = 0;
    for (int c = 0; c < 26; ++c) {
        int u = trie[0].next[c];
