    vec[0] = 1;
    // Multiply initial vector by Mp: result = Mp * vec
    vector<int> res_vec(SZ, 0);
    for (int i = 0; i < SZ; ++i) {
        if (Mp.a[i][0] != 0) {
            res_vec[i] = Mp.a[i][0];
        }
    }

