#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

using ll = long long;

int add(int a, int b) {
    int s = a + b;
    if (s >= MOD) s -= MOD;
    return s;
}

int sub(int a, int b) {
    int s = a - b;
    if (s < 0) s += MOD;
    return s;
}

int mul(int a, int b) {
    return (int)((ll)a * b % MOD);
}

int modpow(int a, long long e = MOD - 2) {
    int r = 1;
    while (e) {
        if (e & 1) r = mul(r, a);
        a = mul(a, a);
        e >>= 1;
    }
    return r;
}

struct Matrix {
    int n;
    vector<vector<int>> a;
    Matrix(int _n = 0, bool ident = false) : n(_n), a(_n, vector<int>(_n)) {
        if (ident) {
            for (int i = 0; i < n; ++i) a[i][i] = 1;
        }
    }
    Matrix operator*(const Matrix& o) const {
        Matrix res(n);
        for (int i = 0; i < n; ++i)
            for (int k = 0; k < n; ++k)
                if (a[i][k])
                    for (int j = 0; j < n; ++j)
                        res.a[i][j] = add(res.a[i][j], mul(a[i][k], o.a[k][j]));
        return res;
    }
};

Matrix mat_pow(Matrix base, long long exp) {
    Matrix res(base.n, true);
    while (exp) {
        if (exp & 1) res = res * base;
        base = base * base;
        exp >>= 1;
    }
    return res;
}

struct Node {
    int child[26];
    int link;
    bool leaf;
    Node() {
        fill(begin(child), end(child), -1);
        link = 0;
        leaf = false;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long m;
    cin >> n >> m;
    vector<string> words(n);
    for (int i = 0; i < n; ++i) cin >> words[i];

    vector<Node> trie(1);
    for (auto& w : words) {
        int v = 0;
        for (char c : w) {
            int idx = c - 'a';
            if (trie[v].child[idx] == -1) {
                trie[v].child[idx] = trie.size();
                trie.emplace_back();
            }
            v = trie[v].child[idx];
        }
        trie[v].leaf = true;
    }

    // Build Aho-Corasick
    queue<int> q;
    trie[0].link = 0;
    for (int c = 0; c < 26; ++c) {
        if (trie[0].child[c] != -1) {
            trie[trie[0].child[c]].link = 0;
            q.push(trie[0].child[c]);
        } else {
            trie[0].child[c] = 0;
        }
    }
    while (!q.empty()) {
        int v = q.front(); q.pop();
        trie[v].leaf = trie[v].leaf || trie[trie[v].link].leaf;
        for (int c = 0; c < 26; ++c) {
            if (trie[v].child[c] != -1) {
                trie[trie[v].child[c]].link = trie[trie[v].link].child[c];
                q.push(trie[v].child[c]);
            } else {
                trie[v].child[c] = trie[trie[v].link].child[c];
            }
        }
    }
    int T = trie.size();

    // Map state (v1, v2) -> id
    vector<vector<int>> id(T, vector<int>(T, -1));
    vector<pair<int,int>> states;
    for (int v1 = 0; v1 < T; ++v1) {
        if (trie[v1].leaf) continue;
        for (int v2 = 0; v2 < T; ++v2) {
            if (trie[v2].leaf) continue;
            id[v1][v2] = states.size();
            states.emplace_back(v1, v2);
        }
    }
    int S = states.size();

    Matrix M(S);
    for (int i = 0; i < S; ++i) {
        int v1 = states[i].first;
        int v2 = states[i].second;
        for (int c = 0; c < 26; ++c) {
            int nv1 = trie[v1].child[c];
            int nv2 = trie[v2].child[c];
            if (trie[nv1].leaf || trie[nv2].leaf) continue;
            int j = id[nv1][nv2];
            M.a[i][j] = add(M.a[i][j], 1);
        }
    }

    Matrix Mp = mat_pow(M, m);
    int start = id[0][0];
    int ans = 0;
    for (int j = 0; j < S; ++j) {
        ans = add(ans, Mp.a[start][j]);
    }
    cout << ans << "\n";
    return 0;
}
